// The regulation's team rules, for the team builder. Generated by `npm run gen-data` (`rules.json`): the format's own
// from Showdown's rule table, and those it doesn't have kept by hand (`scripts/teamRules.ts`).

import DATA from '@/data/generated/rules.json'

export interface TeamRules {
  /** The Pokémon a team has. */
  teamSize: number
  /** The moves a set has. */
  moves: number
  /** One Pokémon of each species, its formes and Megas counting as it. */
  speciesClause: boolean
  /** How many of each item a team holds; no limit without the clause. */
  itemClause: number | null
  /** The most Megas a team takes. */
  megas: number
}

export const RULES: TeamRules = DATA
